import { scenarios } from './scenarios.js';
import {bonusModel,homeModel,emergencyModel,cardModel,cardProfiles,rupee,compact} from './finance.js';
const $=s=>document.querySelector(s);
const chat=$('#conversation');
let state={id:null,answers:[],rate:10,growth:5,delay:2,travel:5000,followups:[]};
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const assistant=(html,extra='',id='')=>`<section class="assistant" ${id?`id="${id}"`:''}><div class="avatar" aria-hidden="true">M</div><div class="message-wrap"><div class="message-name">MoneyCanvas</div><div class="bubble">${html}</div>${extra}</div></section>`;
const user=text=>`<div class="user-message"><div class="user-bubble"><span class="sr-only">You: </span>${escape(text)}</div></div>`;
const facts=items=>`<div class="fact-list">${items.map(f=>`<span class="fact-chip">${f}</span>`).join('')}</div>`;
const scenario=()=>scenarios.find(s=>s.id===state.id);
const answers=()=>Object.fromEntries((scenario()?.questions||[]).slice(0,state.answers.length).map((q,i)=>[q.key,q.options[state.answers[i]].value]));
$('#scenario-nav').innerHTML=scenarios.map(c=>`<button class="nav-item" data-scenario="${c.id}"><span class="nav-icon" aria-hidden="true">${c.icon}</span>${c.short}</button>`).join('');
function home(){state={id:null,answers:[],rate:10,growth:5,delay:2,travel:5000,followups:[]};render();$('#chat-scroll').scrollTop=0;}
function start(id){if(!scenarios.some(s=>s.id===id))throw new Error('Unknown scenario');state={id,answers:[],rate:10,growth:5,delay:2,travel:5000,followups:[]};render();$('#chat-scroll').scrollTop=0;focusChoice();}
function focusChoice(){const element=$('[data-answer]')||$('[data-scenario].scenario-card');element?.focus({preventScroll:true});}
function choose(index){const s=scenario(),q=s?.questions[state.answers.length];if(!q||!q.options[index])throw new Error('That reply is not available');state.answers.push(index);state.followups=[];const a=answers();if(a.delay)state.delay=a.delay;if(a.profile)state.travel=cardProfiles[a.profile].travel;render();const target=$('#active-step')||$('#result-message');target?.scrollIntoView({behavior:'smooth',block:'start'});if(state.answers.length===3)$('#canvas-title')?.focus({preventScroll:true});else focusChoice();}
function render(){
 const s=scenario();$('#chat-title').textContent=s?s.short:'Your next money move';$('#chat-subtitle').textContent=s?'Your situation, made a little clearer':'A conversation with MoneyCanvas';
 document.querySelectorAll('.nav-item').forEach(b=>{const active=b.dataset.scenario===state.id;b.classList.toggle('active',active);if(active)b.setAttribute('aria-current','true');else b.removeAttribute('aria-current');});
 $('#back').hidden=!state.answers.length;$('#composer-hint').textContent=!s?'Pick a scenario to start exploring.':state.answers.length<3?'Choose a reply above to continue.':'Try a what-if, or ask a follow-up below.';
 if(!s){chat.innerHTML=`<div class="welcome-kicker">LET’S MAKE SENSE OF IT</div><h1 class="welcome-title">Your money. Your choices.<br><span>A little more clarity.</span></h1><p class="welcome-text">Big decisions rarely fit into one calculator. Let’s talk through a real-life situation, one small question at a time.</p>${assistant('Hi! What’s on your mind today? Pick a situation and we’ll explore the possibilities together.',`<div class="scenario-grid">${scenarios.map(c=>`<button class="scenario-card" data-scenario="${c.id}"><span class="card-icon" aria-hidden="true">${c.icon}</span><strong>${c.name}</strong><p>${c.description}</p><span class="card-bottom">${c.meta} · 3 questions</span></button>`).join('')}</div><p class="welcome-foot">✦ &nbsp; Choose a reply. See the trade-offs. Try a different outcome.</p>`)}`;return;}
 let html=`<div class="journey-heading"><span class="journey-icon">${s.icon}</span><div><div class="welcome-kicker">LET’S EXPLORE</div><h1>${s.short}</h1></div></div>`+user(s.intro)+assistant(s.context+facts(s.facts));
 s.questions.forEach((q,i)=>{if(i>state.answers.length)return;const complete=i<state.answers.length;html+=assistant(`<div class="step-label">Question ${i+1} of 3</div><p>${q.text}</p>`,complete?'':`<div class="choices" role="group" aria-label="Suggested replies">${q.options.map((o,j)=>`<button class="choice" data-answer="${j}">${o.label}</button>`).join('')}</div>`,complete?'':'active-step');if(complete){const o=q.options[state.answers[i]];html+=user(o.reply)+assistant(o.response);}});
 if(state.answers.length===3){html+=assistant('Here’s your decision canvas. Change one assumption to see what shifts.',`<div class="decision-canvas" id="decision-canvas">${canvas()}</div>`,'result-message');html+=followupSection();}
 chat.innerHTML=html;
}
function slider(id,label,value,min,max,step,display,minLabel,maxLabel){return `<div class="what-if"><div class="what-if-top"><label for="${id}">${label}</label><output for="${id}">${display}</output></div><input type="range" id="${id}" data-control="${id}" min="${min}" max="${max}" step="${step}" value="${value}" aria-valuetext="${display}"><div class="range-labels"><span>${minLabel}</span><span>${maxLabel}</span></div></div>`;}
function bars(items,highlight){const vals=items.map(x=>x.value),min=Math.min(0,...vals),max=Math.max(1,...vals),span=max-min,zero=-min/span*100;return `<div class="bar-chart" role="img" aria-label="${escape(items.map(x=>x.name+': '+rupee(x.value)).join('; '))}">${items.map((x,i)=>{const pos=(x.value-min)/span*100;return `<div class="bar-row ${x.id===highlight?'highlight':''}"><div class="bar-heading"><span>${x.name}${x.id===highlight?' <span class="match-mark">WORTH EXPLORING</span>':''}</span><strong>${compact(x.value)}</strong></div><div class="bar-track"><div class="zero-line" style="left:${zero}%"></div><div class="bar-fill ${x.value<0?'negative':''}" style="left:${Math.min(zero,pos)}%;width:${Math.max(.3,Math.abs(pos-zero))}%;--bar-color:${['#5351dc','#19a48d','#8a79d7','#a2adc2'][i%4]}"></div></div></div>`;}).join('')}</div>`;}
const canvasHead=(title,sub)=>`<div class="canvas-head"><span class="canvas-label">YOUR DECISION CANVAS</span><span class="canvas-tag">Illustrative comparison</span></div><h2 id="canvas-title" tabindex="-1">${title}</h2><p class="canvas-sub">${sub}</p>`;
const insight=(title,text,tone='')=>`<div class="insight ${tone}"><span class="insight-icon" aria-hidden="true">${tone==='caution'?'!':'✦'}</span><div><strong>${title}</strong><p>${text}</p></div></div>`;
const stat=(label,value,sub)=>`<div class="stat"><span>${label}</span><strong>${value}</strong><small>${sub}</small></div>`;
const details=(text)=>`<details class="assumptions"><summary>Assumptions & how this is calculated</summary><div>${text}</div></details>`;
function canvas(){const a=answers();
 if(state.id==='bonus'){
  const rows=bonusModel({rate:state.rate,years:a.years}),chosen=a.buffer==='low'?'cash':a.goal,best=rows.reduce((b,r)=>r.net>b.net?r:b),r=rows.find(x=>x.id===chosen);
  return canvasHead(a.buffer==='low'?'Leave room for the unexpected.':'A bonus can do more than one job.',`₹3 lakh today · ${a.years}-year view · Same ${rupee(r.payment)} monthly budget`)+
  slider('rate','What if investment returns change?',state.rate,-5,15,1,state.rate+'% / year','−5%','15%')+
  `<div class="chart-label">Projected investments + cash − remaining loan</div>`+bars(rows.map(x=>({...x,value:x.net})),chosen)+
  `<div class="stats">${stat('Path to examine first',r.name,a.buffer==='low'?'Keeps the bonus accessible':'Based on what matters to you')}${stat('Loan left at year '+a.years,compact(r.debt),r.debtFree?'Loan clears in month '+r.debtFree:'Monthly repayments continue')}</div>`+
  insight(a.buffer==='low'?'Your buffer changes the conversation.':'The assumptions can change the winner.',a.buffer==='low'?`Keeping the bonus with your ₹80k buffer would cover about 9.5 months of ₹40k essentials, before loan EMIs. That liquidity may matter more than the highest projected return.`:`At ${state.rate}%, “${best.name}” has the highest projected net position. Your preference was “${r.name}”. Certainty, liquidity, and potential growth are different benefits.`)+
  `<p class="canvas-footnote">Investment returns are uncertain; a smooth annual rate is a modelling shortcut. Repayment locks money into the loan.</p>`+
  details(`<p>The loan starts at ₹7.8 lakh, at a fixed 8.7% annual rate, with 60 monthly payments. A ₹3 lakh bonus is repaid, invested, split equally, or kept as cash. All paths use the same original EMI budget.</p><p>Investments compound monthly at the selected annual rate ÷ 12. Any EMI freed by earlier repayment is invested at that rate. Cash earns 0%. The chart subtracts remaining loan debt from investment and cash balances; it is not a return percentage. Your separate emergency fund is excluded. No taxes, fees, prepayment charges, or rate changes are included.</p>`);
 }
 if(state.id==='home'){
  const r=homeModel({years:a.years,growth:state.growth}),over=r.firstMonthly>a.budget,ownerWins=r.difference>0;
  return canvasHead('A home is a financial and a life choice.',`${a.years}-year view · ₹1.38 crore home · ₹48k starting rent`)+
  slider('growth','What if the home’s value grows differently?',state.growth,0,10,1,state.growth+'% / year','0%','10%')+
  `<div class="stats">${stat('First monthly ownership cost',compact(r.firstMonthly),'EMI + maintenance')}${stat('Comfortable monthly budget',compact(a.budget),over?'Ownership exceeds this by '+compact(r.firstMonthly-a.budget):'Ownership is within this amount')}</div>`+
  `<div class="chart-label">Estimated net wealth after ${a.years} years</div>`+bars([{id:'buy',name:'Buy · sale proceeds minus loan',value:r.owner},{id:'rent',name:'Rent · invest upfront cash + savings',value:r.renter}],null)+
  insight(over?'The monthly stretch deserves attention.':`${ownerWins?'Buying':'Renting'} leads by ${compact(Math.abs(r.difference))} in this projection.`,over?`The first-year ownership cost is ${rupee(r.firstMonthly)} a month, above your ${rupee(a.budget)} comfort level. A lower home price or larger upfront amount would change affordability.`:`${a.priority==='flex'?'You value the freedom to move. Renting also avoids the effort and uncertainty of selling.':'You value a permanent home. That stability matters alongside the projected financial gap.'}`,over?'caution':'')+
  details(`<p>₹40 lakh upfront pays 7% of the home price in purchase costs (${rupee(r.buyCosts)}), leaving ${rupee(r.down)} for the down payment. The resulting ${rupee(r.loan)} loan is amortized monthly over 20 years at 8.5%.</p><p>Rent and maintenance rise 5% annually. Maintenance starts at 1% of the home price per year. The renter invests the ₹40 lakh and monthly savings at 8% annual nominal return, compounded monthly. If renting becomes more expensive, the owner invests that difference instead. Home appreciation uses the slider; sale costs are 2%. Remaining loan is deducted on sale. Taxes, tax benefits, insurance, renovation, and investment fees are excluded. Rates are illustrative, not current market quotes.</p>`);
 }
 if(state.id==='emergency'){
  const rows=emergencyModel({delay:state.delay,essential:a.essential,priority:a.priority}),chosen=a.priority==='buffer'?'fd':'savings',r=rows.find(x=>x.id===chosen),short=rows.every(x=>x.afterDelay<0);
  return canvasHead('Protect your breathing room.',`${state.delay} months without income · ${rupee(a.essential)} monthly essentials`)+
  slider('delay','What if the next payment is later?',state.delay,1,6,1,state.delay+' month'+(state.delay===1?'':'s'),'1 month','6 months')+
  `<div class="chart-label">Bank cash after the expense and income delay</div>`+bars(rows.map(x=>({...x,value:x.afterDelay})),chosen)+
  `<div class="comparison-grid">${rows.map(x=>`<div class="option-tile ${x.id===chosen?'selected':''}"><h3>${x.name}</h3><strong>${x.runway.toFixed(1)} months</strong><span>Bank-cash runway</span><p>${x.note}</p><div class="tile-detail">Cost: <b>${rupee(x.cost)}</b><br>Monthly EMI: <b>${rupee(x.emi)}</b><br>FD left: <b>${compact(x.fd)}</b></div></div>`).join('')}</div>`+
  insight(short?'All three paths need another source of cash.':r.afterDelay<0?'Your preferred path runs short on bank cash.':'Look at both cost and access.',short?'At this delay, bank cash runs short in every path. Remaining fixed deposits may cover the gap; this chart intentionally keeps them separate.':r.afterDelay<0?`“${r.name}” leaves a ${rupee(-r.afterDelay)} cash shortfall after ${state.delay} months. Remaining FDs are ${compact(r.fd)}; accessing them would change this projection.`:`“${r.name}” leaves ${rupee(r.afterDelay)} in bank cash. An EMI preserves more money today but adds ${rupee(rows[2].emi)} to every month’s outgo.`,short||r.afterDelay<0?'caution':'')+
  details(`<p>Initial balances: ₹2 lakh in bank savings and ₹3 lakh in FDs. A ₹1 lakh expense is paid now. FD withdrawal assumes a ₹1,000 total penalty / lost-interest cost paid from bank cash. The EMI option uses 15% annual interest over 12 months, with no additional fees.</p><p>Bank cash after delay = bank balance after payment − delay × (essential expenses + EMI) − FD withdrawal cost, if applicable. Negative amounts mean a shortfall. Runway uses only bank cash; FD balances are shown separately. No incoming payments, interest earnings, or additional expenses are assumed. FD cost is a sample assumption, not a bank quote.</p>`);
 }
 const rows=cardModel({...a,travel:state.travel}),r=rows.find(x=>x.eligible),total=r.spend.travel+r.spend.dining+r.spend.other;
 return canvasHead('The best rewards are the ones you’ll use.',`${rupee(total)} monthly spending · ${a.redeem==='cash'?'Cashback':'Travel'} redemption`)+
 slider('travel','What if your monthly travel spending changes?',state.travel,0,30000,1000,rupee(state.travel),'₹0','₹30k')+
 `<div class="chart-label">Estimated annual value after fee + tax</div>`+bars(rows.map(x=>({...x,value:x.net})),r.id)+
 `<div class="stats">${stat('Best fit for your preferences',r.name,a.fee==='none'?'Matches your no-fee preference':'Highest net value at this spending')}${stat('Estimated annual net value',rupee(r.net),rupee(r.rewards)+' rewards − '+rupee(r.annualFee)+' fee')}</div>`+
 insight('A reward rate is only half the story.',a.redeem==='cash'?'Travel Miles points are valued at 50% of their travel value when redeemed for cash in this demo. That one choice can change the ranking.':'You plan to redeem for travel, so Travel Miles uses its full illustrative redemption value. The annual fee still needs to pay for itself.')+
 `<div class="card-rules">${rows.map(x=>`<p><strong>${x.name}</strong>${!x.eligible?' <span class="muted">· outside your no-fee preference</span>':''}<br>${x.detail} Annual fee including tax: ${rupee(x.annualFee)}.</p>`).join('')}</div>`+
 details(`<p>These are fictional products, not real card offers. Everyday Cash: 1% on all spending, no fee. Flexible Plus: 5% on dining capped at ₹500 a month, 1% on other spend, ₹999 annual fee. Travel Miles: 4% on travel and 1% elsewhere when redeemed for travel, half that value for cash, ₹2,999 annual fee. Fees include an assumed 18% tax; no waivers or welcome bonuses.</p><p>Annual net value = 12 × monthly reward value − annual fee with tax. The travel slider changes travel spend while dining and other spending stay at your chosen profile. This assumes bills paid in full; interest, exclusions, merchant classifications, and redemption restrictions are omitted.</p>`);
}
const followups=[{id:'changes',label:'What could change this result?'},{id:'summary',label:'Give me the short version'}];
function followupText(id){const a=answers();if(id==='changes')return {
 bonus:`For this ${a.years}-year example, investment performance, loan-rate changes, taxes, or prepayment fees can change the numbers. A new cash need can change what feels right even when the arithmetic stays the same. Try the return slider at 0% and 12%.`,
 home:'Try home appreciation at 2% and 8%. The wealth comparison is sensitive to that assumption. A different stay length, loan rate, renovation bill, or ability to consistently invest the rent savings could also change the result.',
 emergency:'A delayed client payment, a second expense, or FD access restrictions can change the cash picture. The delay slider shows bank-cash shortfalls; a remaining FD is still an asset even though it is not counted as bank cash.',
 card:'A change in spending or how you redeem points can reverse the ranking. Actual cards add exclusions, caps, fee waivers, and changing terms. These three fictional cards keep the underlying comparison easy to see.'
 }[state.id];
 if(state.id==='bonus'){const rows=bonusModel({rate:state.rate,years:a.years}),best=rows.reduce((b,x)=>x.net>b.net?x:b);return `At the current ${state.rate}% return assumption, ${best.name.toLowerCase()} has the highest projected net position after ${a.years} years (${rupee(best.net)}). ${a.buffer==='low'?'Your two-month emergency buffer also makes retaining cash worth considering.':'Your separate six-month buffer leaves more room to explore repayment, investing, or a split.'} This is a comparison, not a guaranteed outcome.`;}
 if(state.id==='home'){const r=homeModel({years:a.years,growth:state.growth});return `In this ${a.years}-year model at ${state.growth}% home appreciation, ${r.difference>0?'buying':'renting'} leads by ${rupee(Math.abs(r.difference))}. Ownership starts at ${rupee(r.firstMonthly)} a month including maintenance. You said ${a.priority==='flex'?'flexibility':'stability'} matters most; keep that beside the financial result.`;}
 if(state.id==='emergency'){const rows=emergencyModel({delay:state.delay,essential:a.essential});return `After ${state.delay} months without income: savings leaves ${rupee(rows[0].afterDelay)}, an FD withdrawal leaves ${rupee(rows[1].afterDelay)}, and EMI leaves ${rupee(rows[2].afterDelay)} in bank cash. A negative figure is a shortfall. The EMI costs about ${rupee(rows[2].cost)} in total interest over 12 months.`;}
 const r=cardModel({...a,travel:state.travel}).find(x=>x.eligible);return `${r.name} best matches your selected preferences in this simplified model, with ${rupee(r.net)} estimated yearly net value. That uses ${a.redeem==='cash'?'cash':'travel'} redemption and ${rupee(state.travel)} of monthly travel spending. All three cards are fictional.`;
}
function followupSection(){return `<div id="followup-area">${state.followups.map(f=>user(followups.find(x=>x.id===f.id).label)+assistant(f.text)).join('')}<div class="followup-choices"><div class="step-label">KEEP EXPLORING</div><div class="choices">${followups.map(f=>`<button class="choice" data-followup="${f.id}">${f.label}</button>`).join('')}<button class="choice" data-restart>Change my answers</button><button class="choice primary" data-home>Try another scenario</button></div></div></div>`;}
function updateControl(key,value){const limits={rate:[-5,15],growth:[0,10],delay:[1,6],travel:[0,30000]};if(!limits[key]||!Number.isFinite(value)||value<limits[key][0]||value>limits[key][1])throw new Error('Invalid what-if value');state[key]=value;state.followups=[];const template=document.createElement('div');template.innerHTML=canvas();const fresh=[...template.children];[...$('#decision-canvas').children].forEach((old,i)=>{if(old.classList.contains('what-if')){old.querySelector('output').textContent=fresh[i].querySelector('output').textContent;old.querySelector('input').setAttribute('aria-valuetext',fresh[i].querySelector('input').getAttribute('aria-valuetext'));}else old.replaceWith(fresh[i]);});$('#followup-area').outerHTML=followupSection();}
document.addEventListener('click',e=>{
 const b=e.target.closest('button,a.brand');if(!b)return;
 if(b.matches('[data-home],.brand')){e.preventDefault();home();focusChoice();}
 else if(b.dataset.scenario)start(b.dataset.scenario);
 else if(b.dataset.answer!==undefined)choose(Number(b.dataset.answer));
 else if(b.matches('#restart,[data-restart]')){if(state.id)start(state.id);else home();}
 else if(b.id==='back'&&state.answers.length){state.answers.pop();state.followups=[];render();$('#active-step')?.scrollIntoView({behavior:'smooth',block:'start'});focusChoice();}
 else if(b.dataset.followup){const id=b.dataset.followup;state.followups.push({id,text:followupText(id)});$('#followup-area').outerHTML=followupSection();$('#followup-area .assistant:last-of-type')?.scrollIntoView({behavior:'smooth',block:'start'});}
});
document.addEventListener('input',e=>{if(e.target.dataset.control)updateControl(e.target.dataset.control,Number(e.target.value));});
// Optional browser agent support; no external service or model is contacted.
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=tool=>{try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}};
 register({name:'start_moneycanvas_scenario',description:'Start one of the four guided MoneyCanvas sample conversations.',inputSchema:{type:'object',properties:{scenario:{type:'string',enum:scenarios.map(s=>s.id)}},required:['scenario'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{start(input.scenario);return {scenario:state.id,question:scenario().questions[0].text};}});
 register({name:'choose_moneycanvas_reply',description:'Choose a zero-based reply index in the current guided question.',inputSchema:{type:'object',properties:{index:{type:'integer',minimum:0,maximum:2}},required:['index'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!Number.isInteger(input.index))throw new Error('Reply index must be an integer');choose(input.index);return {scenario:state.id,answers:answers(),complete:state.answers.length===3};}});
 addEventListener('pagehide',()=>lifecycle.abort());
}
home();
